svg.script:
/**/
(function() {
  'use strict';

  var root = document.getElementById('a12p10h-svg-root');
  var toggleBtn = document.getElementById('a12p10h-mode-toggle');
  var toggleTxt = document.getElementById('a12p10h-toggle-txt');

  var featEspinha = document.getElementById('a12p10h-feature-espinha');
  var featTuberosidade = document.getElementById('a12p10h-feature-tuberosidade');
  var cardEspinha = document.getElementById('a12p10h-card-espinha');
  var cardTuberosidade = document.getElementById('a12p10h-card-tuberosidade');

  var currentMode = 'pistas';

  function toggleMode() {
    if (currentMode === 'pistas') {
      currentMode = 'quiz';
      root.setAttribute('data-mode', 'quiz');
      toggleTxt.textContent = 'MODO: TREINE O OLHO (SEM PISTAS)';
    } else {
      currentMode = 'pistas';
      root.setAttribute('data-mode', 'pistas');
      toggleTxt.textContent = 'MODO: COM PISTAS (PADRÃO)';
    }
  }

  if (toggleBtn) {
    toggleBtn.addEventListener('click', toggleMode);
    toggleBtn.addEventListener('keydown', function(e) {
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        toggleMode();
      }
    });
  }

  function selectFeature(target) {
    featEspinha.classList.remove('a12p10h-active');
    featTuberosidade.classList.remove('a12p10h-active');
    cardEspinha.classList.remove('a12p10h-active');
    cardTuberosidade.classList.remove('a12p10h-active');

    if (target === 'espinha') {
      featEspinha.classList.add('a12p10h-active');
      cardEspinha.classList.add('a12p10h-active');
    } else if (target === 'tuberosidade') {
      featTuberosidade.classList.add('a12p10h-active');
      cardTuberosidade.classList.add('a12p10h-active');
    }
  }

  if (featEspinha) featEspinha.addEventListener('click', function() { selectFeature('espinha'); });
  if (cardEspinha) cardEspinha.addEventListener('click', function() { selectFeature('espinha'); });

  if (featTuberosidade) featTuberosidade.addEventListener('click', function() { selectFeature('tuberosidade'); });
  if (cardTuberosidade) cardTuberosidade.addEventListener('click', function() { selectFeature('tuberosidade'); });

  [featEspinha, cardEspinha].forEach(function(el) {
    if (el) {
      el.addEventListener('keydown', function(e) {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          selectFeature('espinha');
        }
      });
    }
  });

  [featTuberosidade, cardTuberosidade].forEach(function(el) {
    if (el) {
      el.addEventListener('keydown', function(e) {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          selectFeature('tuberosidade');
        }
      });
    }
  });

})();
/**/
